}

ruleBookInfo.init:
@js:
(function(){
  var id = String(baseUrl).replace(/^.*?bookId=([0-9]+).*$/,'$1');
  if(!/^[0-9]+$/.test(id)){ try{ id = String(book.bookUrl||'').replace(/^.*?bookId=([0-9]+).*$/,'$1'); }catch(e){} }
  if(!/^[0-9]+$/.test(id)) return '{}';
  var body = 'bookId=' + id + '&needChapter=0&needRecommend=0';
  var raw = QC_post('/goway/goread/app/book/detail','',body,'goway.reader.yueyouxs.com',java);
  var j = {}; try{ j = JSON.parse(raw); }catch(e){}
  var b = (j.data && j.data.book) || {};
  return JSON.stringify({
    name: QC_clean(b.bookName), author: QC_clean(b.authorName),
    kind: (b.classifyName||'') + '/' + (b.classifySecondName||'') + '/' + (b.tag||''),
    wordCount: b.wordsDesc||'', lastChapter: b.latestChapterName||'',
    intro: String(b.intro||'').replace(/\r/g,''), coverUrl: b.bookPic||'',
    tocUrl: 'https://dl.reader.yueyouxs.com/userCenter/getChapterList?bookId=' + id + '&chapterId=0&isAll=1'
  });
})()

ruleContent.content:
@js:
(function(){
  var u = String(baseUrl);
  var mb = u.match(/bookId=([0-9]+)/), mc = u.match(/chapterId=([0-9]+)/);
  if(!mb || !mc) return '';
  var body = 'inBuyView=false&ossSwitch=0&feeState=0&chapterId=' + mc[1] + '&useSrvAutoBuy=1&readCount=0&autoBuy=false&isOssed=0&bookId=' + mb[1];
  var raw = QC_post('/userCenter/v310/downloadChapter','',body,'dl.reader.yueyouxs.com',java);
  var j = {}; try{ j = JSON.parse(raw); }catch(e){}
  var cu = j.data && j.data.contentUrl;
  if(!cu) return '［获取失败］' + (j.msg||'无正文直链');
  var txt = String(java.ajax(cu));
  if(txt.indexOf('<?xml')===0 || txt.indexOf('<Error')>=0) return '［获取失败］' + txt.slice(0,120);
  return txt.replace(/\r/g,'').replace(/^\s+|\s+$/g,'');
})()

ruleExplore.bookList:
@js:
(function(){
  var raw=String(result || (typeof src!=='undefined'?src:'') || '');
  var j={};try{j=JSON.parse(raw);}catch(e){}
  var arr=[];
  if(j.data){
    if(Array.isArray(j.data)) arr=j.data;
    else if(j.data.list && Array.isArray(j.data.list)) arr=j.data.list;
    else if(j.data.bookList && Array.isArray(j.data.bookList)) arr=j.data.bookList;
    else if(j.data.rankList && Array.isArray(j.data.rankList)) arr=j.data.rankList;
  }
  var list=new Packages.java.util.ArrayList();
  for(var i=0;i<arr.length;i++){
    var b=arr[i]; if(!b) continue;
    var bid=b.bookId||b.id||b.wapBookId; if(!bid) continue;
    var nm=b.bookName||'';
    list.add(JSON.stringify({
      name:QC_clean(nm), author:QC_clean(b.authorName||''),
      coverUrl:b.bookPic||'',
      kind:(b.classifyName||'')+'/'+(b.classifySecondName||'')+' · '+(b.wordsDesc||''),
      intro:String(b.introOrRec||b.intro||'').replace(/\r/g,''),
      bookUrl:'https://goway.reader.yueyouxs.com/goway/goread/app/book/detail?bookId='+bid
    }));
  }
  return list;
})()

