ruleToc.chapterList:
@js:
(function(){
  var id = String(baseUrl).replace(/^.*?bookId=([0-9]+).*$/,'$1');
  if(!/^[0-9]+$/.test(id)) return new Packages.java.util.ArrayList();
  var qe = 'bookId=' + id + '&chapterId=0&isAll=1';
  var txt = QC_post('/userCenter/getChapterList', qe, 'tmp=', 'dl.reader.yueyouxs.com', java);
  var j = {}; try{ j = JSON.parse(txt); }catch(e){}
  var arr = (j.data && Array.isArray(j.data)) ? j.data : [];
  var list = new Packages.java.util.ArrayList();
  for(var i=0;i<arr.length;i++){
    var c = arr[i];
    list.add(JSON.stringify({
      name: String(c.chapterName||''),
      url: 'https://dl.reader.yueyouxs.com/userCenter/v310/downloadChapter?bookId=' + id + '&chapterId=' + c.chapterId,
      vip: (c.isFee===1 || c.vip===1)
    }));
  }
  return list;
})()

